  "I confirm that the personal, contact, vehicle, insurance, and identity details I submit are true, accurate, and complete to the best of my knowledge. I agree to mAIRide's terms of use, safety rules, verification checks, and community standards. I understand that false, misleading, or incomplete information may lead to suspension, account closure, or legal reporting where required.";

const MARKETING_DISCLOSURE_TEXT =
  "I agree to receive account updates, safety notices, service alerts, offers, and promotional communications from mAIRide by email, SMS, and WhatsApp. I understand I can change these preferences later if mAIRide provides that option.";

const DRIVER_DECLARATION_TEXT =
  "I confirm that my vehicle, registration, license, insurance, and identity documents belong to me or are lawfully under my control, and that every document and image submitted is current, genuine, and captured by me during this onboarding process.";

type VerificationMarker = {
  id: string;
  label: string;
  geoTag: { lat: number; lng: number; timestamp: number };
};

type AppDialogTone = 'info' | 'success' | 'warning' | 'error';

type AppDialogDetail = {
  title?: string;
  message: string;
  tone?: AppDialogTone;
};

const getBookingNegotiationField = <T,>(booking: Booking, key: string): T | undefined => {
  const nested = (booking as any)?.data?.[key];
  if (nested !== undefined && nested !== null && nested !== '') {
    return nested as T;
  }
  const topLevel = (booking as any)?.[key];
  if (topLevel !== undefined && topLevel !== null && topLevel !== '') {
    return topLevel as T;
  }
  return undefined;
};

const getFirstBookingNegotiationField = <T,>(booking: Booking, keys: string[]): T | undefined => {
  for (const key of keys) {
    const value = getBookingNegotiationField<T>(booking, key);
    if (value !== undefined && value !== null && value !== '') return value;
  }
  return undefined;
};

const getRealtimeRowData = <T extends { id?: string }>(row: any): T => {
  const base = row?.data && typeof row.data === 'object' ? row.data : {};
  return {
    ...base,
    ...(row?.id ? { id: row.id } : {}),
    ...(row?.uid ? { uid: row.uid } : {}),
    ...(row?.ride_id ? { rideId: row.ride_id } : {}),
    ...(row?.consumer_id ? { consumerId: row.consumer_id } : {}),
    ...(row?.driver_id ? { driverId: row.driver_id } : {}),
    ...(row?.status ? { status: row.status } : {}),
    ...(row?.created_at ? { createdAt: row.created_at } : {}),
    ...(row?.updated_at ? { updatedAt: row.updated_at } : {}),
    ...(row?.driver_bid !== undefined ? { driverBid: row.driver_bid } : {}),
    ...(row?.consumer_bid !== undefined ? { consumerBid: row.consumer_bid } : {}),
    ...(row?.ride_request_id ? { linkedTravelerRequestId: row.ride_request_id } : {}),
    ...(row?.request_id ? { linkedTravelerRequestId: row.request_id } : {}),
    ...(row?.booking_id ? { bookingId: row.booking_id } : {}),
    ...(row?.negotiated_fare !== undefined ? { negotiatedFare: row.negotiated_fare } : {}),
    ...(row?.counter_fare !== undefined ? { negotiatedFare: row.counter_fare } : {}),
  } as T;
};

const firstFiniteNumber = (...values: unknown[]) => {
  for (const value of values) {
    const next = Number(value);
    if (Number.isFinite(next)) return next;
  }
  return 0;
};

const isTravelerRequestStorageStatus = (status: unknown) =>
  ['traveler_request_open', 'traveler_request_matched', 'traveler_request_cancelled'].includes(
    String(status || '').trim().toLowerCase()
  );

const normalizeTravelerRideRequest = (row: any): TravelerRideRequest => {
  const data = row?.data && typeof row.data === 'object' ? row.data : row || {};
  const topLevelStatus = String(row?.status || '').trim().toLowerCase();
  const nestedStatus = String(data.status || '').trim().toLowerCase();
  const status: TravelerRideRequest['status'] =
    topLevelStatus === 'traveler_request_cancelled' || nestedStatus === 'cancelled'
      ? 'cancelled'
      : topLevelStatus === 'traveler_request_matched' || nestedStatus === 'matched' || topLevelStatus === 'negotiating'
        ? 'matched'
        : 'open';
  const fare = firstFiniteNumber(data.fare, row?.fare, data.listedFare, data.negotiatedFare, data.totalPrice);
  const now = new Date().toISOString();

  return {
    ...data,
    id: String(row?.id || data.id || ''),
    consumerId: String(row?.consumer_id || row?.consumerId || data.consumerId || data.consumer_id || ''),
    consumerName: String(data.consumerName || data.displayName || data.userName || 'Traveler'),
    consumerPhone: String(data.consumerPhone || data.phoneNumber || ''),
    origin: String(data.origin || row?.origin || ''),
    destination: String(data.destination || row?.destination || ''),
    originLocation: data.originLocation || null,
    destinationLocation: data.destinationLocation || null,
    fare,
    seatsNeeded: Math.max(1, firstFiniteNumber(data.seatsNeeded, data.seatsBooked, 1)),
    departureTime: String(data.departureTime || row?.departure_time || row?.created_at || now),
    departureDay: data.departureDay || 'today',
    departureDayLabel: data.departureDayLabel || 'Today',
    departureClock: data.departureClock || '09:00',
    departureNote:
      data.departureNote ||
      'Planned departure time may vary due to traffic, road, and operational conditions.',
    status,
    matchedRideId: data.matchedRideId || row?.ride_id || data.rideId || undefined,
    matchedDriverId: data.matchedDriverId || row?.driver_id || data.driverId || undefined,
    matchedAt: data.matchedAt,
    createdAt: String(data.createdAt || row?.created_at || now),
    updatedAt: String(data.updatedAt || row?.updated_at || row?.created_at || now),
  };
};

const normalizeNegotiationBooking = <T extends Booking>(booking: T): T => {
  const data = (booking as any)?.data || {};
  const actor = data.negotiationActor || (booking as any).negotiationActor;
  const driverBid =
    data.driverBid ?? data.driver_bid ?? (booking as any).driverBid ?? (booking as any).driver_bid;
  const consumerBid =
    data.consumerBid ??
    data.consumer_bid ??
    data.riderOffer ??
    data.rider_offer ??
    (booking as any).consumerBid ??
    (booking as any).consumer_bid ??
    (booking as any).riderOffer ??
    (booking as any).rider_offer;
  const activeNegotiatedFare =
    actor === 'driver' && driverBid !== undefined
      ? driverBid
      : actor === 'consumer' && consumerBid !== undefined
        ? consumerBid
        : data.negotiatedFare ?? (booking as any).negotiatedFare;
  return {
    ...booking,
    ...(data.isDemo !== undefined ? { isDemo: data.isDemo } : {}),
    ...(data.is_demo !== undefined ? { is_demo: data.is_demo } : {}),
    ...(data.rideId ? { rideId: data.rideId } : {}),
    ...(data.ride_id ? { ride_id: data.ride_id } : {}),
    ...(data.driverId ? { driverId: data.driverId } : {}),
    ...(data.driver_id ? { driverId: data.driver_id } : {}),
    ...(data.consumerId ? { consumerId: data.consumerId } : {}),
    ...(data.consumer_id ? { consumerId: data.consumer_id } : {}),
    ...(data.travelerId ? { travelerId: data.travelerId } : {}),
    ...(data.traveler_id ? { travelerId: data.traveler_id } : {}),
    ...(data.linkedTravelerRequestId ? { linkedTravelerRequestId: data.linkedTravelerRequestId } : {}),
    ...(data.rideRequestId ? { rideRequestId: data.rideRequestId } : {}),
    ...(data.negotiationId ? { negotiationId: data.negotiationId } : {}),
    ...(data.negotiation_id ? { negotiationId: data.negotiation_id } : {}),
    ...(data.negotiationEvent ? { negotiationEvent: data.negotiationEvent } : {}),
    ...(data.counterOfferStatus ? { counterOfferStatus: data.counterOfferStatus } : {}),
    ...(activeNegotiatedFare !== undefined ? { negotiatedFare: activeNegotiatedFare } : {}),
    ...(driverBid !== undefined ? { driverBid } : {}),
    ...(consumerBid !== undefined ? { consumerBid } : {}),
    ...(data.negotiationStatus ? { negotiationStatus: data.negotiationStatus } : {}),
    ...(data.negotiationActor ? { negotiationActor: data.negotiationActor } : {}),
    ...(data.driverCounterPending !== undefined ? { driverCounterPending: data.driverCounterPending } : {}),
    ...(data.status ? { status: data.status } : {}),
    ...(data.fare !== undefined ? { fare: data.fare } : {}),
    ...(data.listedFare !== undefined ? { listedFare: data.listedFare } : {}),
    ...(data.updatedAt ? { updatedAt: data.updatedAt } : {}),
    ...(data.rideRetired !== undefined ? { rideRetired: data.rideRetired } : {}),
    ...(data.driverPhone ? { driverPhone: data.driverPhone } : {}),
    ...(data.consumerPhone ? { consumerPhone: data.consumerPhone } : {}),
  };
};

const getPendingNegotiationActor = (booking: Booking): 'driver' | 'consumer' | null => {
  const negotiatedFare = Number(getBookingNegotiationField<number | string>(booking, 'negotiatedFare'));
  const negotiationStatus = String(getBookingNegotiationField<string>(booking, 'negotiationStatus') || '');
  const negotiationActor = String(getBookingNegotiationField<string>(booking, 'negotiationActor') || '');
  const driverCounterPending = Boolean(getBookingNegotiationField<boolean>(booking, 'driverCounterPending'));

  if (!Number.isFinite(negotiatedFare) || negotiationStatus !== 'pending') {
    return null;
  }

  if (negotiationActor === 'driver') {
    return 'driver';
  }

  if (negotiationActor === 'consumer') {
    return 'consumer';
  }

  if (driverCounterPending) {
    return 'driver';
  }

  return null;
};

const hasPendingDriverCounterOffer = (booking: Booking) => {
  return getPendingNegotiationActor(booking) === 'driver';
};

const hasPendingTravelerCounterOffer = (booking: Booking) => {
  const negotiatedFare = Number(getBookingNegotiationField<number | string>(booking, 'negotiatedFare'));
  const negotiationStatus = String(getBookingNegotiationField<string>(booking, 'negotiationStatus') || '');
  const fare = Number(getBookingNegotiationField<number | string>(booking, 'fare'));

  if (!Number.isFinite(negotiatedFare) || negotiationStatus !== 'pending') {
    return false;
  }

  return getPendingNegotiationActor(booking) === 'consumer' && negotiatedFare !== fare;
};

const loadNegotiationThreadBookings = async (seedBooking: Booking) => {
  const rideId = seedBooking.rideId;
  const consumerId = seedBooking.consumerId;

  if (!rideId && !consumerId) {
    return [seedBooking];
  }

  const threadQuery = rideId
    ? query(collection(db, 'bookings'), where('rideId', '==', rideId))
    : query(collection(db, 'bookings'), where('consumerId', '==', consumerId));
  const snapshot = await getDocs(
    threadQuery
  );

  const rows = snapshot.docs.map((snapshotDoc) => ({ id: snapshotDoc.id, ...(snapshotDoc.data() as Booking) }));
  const threadKey = getBookingThreadKey(seedBooking);
  const threadRows = rows.filter((booking) => getBookingThreadKey(booking) === threadKey);

  return threadRows.length ? threadRows : [seedBooking];
};

const persistCounterOfferThroughCompatStore = async (
  seedBooking: Booking,
  actor: 'driver' | 'consumer',
  fare: number
) => {
  const updatedAt = new Date().toISOString();
  const threadRows = await loadNegotiationThreadBookings(seedBooking);

  await Promise.all(
    threadRows.map((booking) =>
      updateDoc(doc(db, 'bookings', booking.id), {
        negotiatedFare: fare,
        ...(actor === 'driver' ? { driverBid: fare } : { consumerBid: fare }),
        negotiationStatus: 'pending',
        negotiationActor: actor,
        driverCounterPending: actor === 'driver',
        status: 'negotiating',
        rideRetired: false,
        'data.negotiatedFare': fare,
        ...(actor === 'driver' ? { 'data.driverBid': fare } : { 'data.consumerBid': fare }),
        'data.negotiationStatus': 'pending',
        'data.negotiationActor': actor,
        'data.driverCounterPending': actor === 'driver',
        'data.status': 'negotiating',
        'data.rideRetired': false,
        updatedAt,
        'data.updatedAt': updatedAt,
      })
    )
  );

  if (seedBooking.rideId) {
    await updateDoc(doc(db, 'rides', seedBooking.rideId), {
      status: 'negotiating',
      negotiationStatus: 'pending',
      negotiationActor: actor,
      updatedAt,
      'data.status': 'negotiating',
      'data.negotiationStatus': 'pending',
      'data.negotiationActor': actor,
      'data.updatedAt': updatedAt,
    }).catch((error) => {
      reportFirestoreError(error, OperationType.UPDATE, `rides/${seedBooking.rideId}`);
    });
  }

  return updatedAt;
};

const persistNegotiationResolutionThroughCompatStore = async (
  seedBooking: Booking,
  actor: 'driver' | 'consumer',
  action: 'accepted' | 'rejected' | 'confirmed',
  options?: {
    acceptedFare?: number;
    driverPhone?: string;
  }
) => {
  const updatedAt = new Date().toISOString();
  const threadRows = await loadNegotiationThreadBookings(seedBooking);
  const normalizedAction = action === 'confirmed' ? 'accepted' : action;
  const nextStatus = normalizedAction === 'accepted' ? 'confirmed' : 'rejected';
  const nextNegotiationStatus = normalizedAction === 'accepted' ? 'accepted' : 'rejected';
  const nextFare =
    normalizedAction === 'accepted'
      ? options?.acceptedFare ?? getNegotiationDisplayFare(seedBooking)
      : undefined;
  const nextFareBreakdown =
    normalizedAction === 'accepted' && Number.isFinite(nextFare)
      ? calculateServiceFee(Number(nextFare))
      : null;

  await Promise.all(
    threadRows.map((booking) =>
      updateDoc(doc(db, 'bookings', booking.id), {
        ...(normalizedAction === 'accepted' && Number.isFinite(nextFare) ? { fare: nextFare } : {}),
        ...(normalizedAction === 'accepted' && Number.isFinite(nextFare) && nextFareBreakdown
          ? {
              serviceFee: nextFareBreakdown.baseFee,
              gstAmount: nextFareBreakdown.gstAmount,
              totalPrice: Number(nextFare) + nextFareBreakdown.totalFee,
            }
          : {}),
        status: nextStatus,
        negotiationStatus: nextNegotiationStatus,
        negotiationActor: actor,
        driverCounterPending: false,
        rideRetired: normalizedAction === 'rejected',
        ...(normalizedAction === 'accepted' && Number.isFinite(nextFare) ? { 'data.fare': nextFare } : {}),
        ...(normalizedAction === 'accepted' && Number.isFinite(nextFare) && nextFareBreakdown
          ? {
              'data.serviceFee': nextFareBreakdown.baseFee,
              'data.gstAmount': nextFareBreakdown.gstAmount,
              'data.totalPrice': Number(nextFare) + nextFareBreakdown.totalFee,
            }
          : {}),
        'data.status': nextStatus,
        'data.negotiationStatus': nextNegotiationStatus,
        'data.negotiationActor': actor,
        'data.driverCounterPending': false,
        'data.rideRetired': normalizedAction === 'rejected',
        ...(options?.driverPhone ? { driverPhone: options.driverPhone } : {}),
        ...(options?.driverPhone ? { 'data.driverPhone': options.driverPhone } : {}),
        updatedAt,
        'data.updatedAt': updatedAt,
      })
    )
  );

  if (normalizedAction === 'accepted' && seedBooking.rideId) {
    await updateDoc(doc(db, 'rides', seedBooking.rideId), {
      status: 'full',
      updatedAt,
    });
  }

  return updatedAt;
};

const persistCommunicationMessageThroughCompatStore = async (
  seedBooking: Booking,
  message: BookingCommunicationMessage
) => {
  const updatedAt = new Date().toISOString();
  const threadRows = await loadNegotiationThreadBookings(seedBooking);

  await Promise.all(
    threadRows.map((booking) => {
      const currentThread = getCommunicationThread(booking);
      const nextThread = [...currentThread, message].slice(-12);
      return updateDoc(doc(db, 'bookings', booking.id), {
        communicationThread: nextThread,
        'data.communicationThread': nextThread,
        updatedAt,
        'data.updatedAt': updatedAt,
      });
    })
  );

  return updatedAt;
};

const applyThreadNegotiationState = (
  seedBooking: Booking,
  actor: 'driver' | 'consumer',
  status: 'pending' | 'negotiating' | 'confirmed' | 'rejected',
  options?: {
    fare?: number;
    driverPhone?: string;
    negotiationStatus?: 'pending' | 'accepted' | 'rejected';
    driverCounterPending?: boolean;
    rideRetired?: boolean;
  }
) => {
  const updatedAt = new Date().toISOString();
  return (candidate: Booking) =>
    getBookingThreadKey(candidate) === getBookingThreadKey(seedBooking)
      ? {
          ...candidate,
          ...(options?.fare !== undefined ? { fare: options.fare } : {}),
          ...(options?.fare !== undefined ? { negotiatedFare: options.fare } : {}),
          status,
          negotiationStatus:
            options?.negotiationStatus ?? (status === 'confirmed' ? 'accepted' : status === 'rejected' ? 'rejected' : 'pending'),
          negotiationActor: actor,
          driverCounterPending: options?.driverCounterPending ?? (actor === 'driver' && status !== 'confirmed' && status !== 'rejected'),
          ...(options?.driverPhone ? { driverPhone: options.driverPhone } : {}),
          ...(options?.rideRetired !== undefined ? { rideRetired: options.rideRetired } : {}),
          updatedAt,
        }
      : candidate;
};

const getNegotiationDisplayFare = (booking: Booking) => {
  const negotiationActor = String(getBookingNegotiationField<string>(booking, 'negotiationActor') || '');
  const driverBid = Number(getFirstBookingNegotiationField<number | string>(booking, ['driverBid', 'driver_bid']));
  const consumerBid = Number(getFirstBookingNegotiationField<number | string>(booking, ['consumerBid', 'consumer_bid', 'riderOffer', 'rider_offer']));
  const negotiatedFare = Number(getBookingNegotiationField<number | string>(booking, 'negotiatedFare'));
  const negotiationStatus = String(getBookingNegotiationField<string>(booking, 'negotiationStatus') || '');
  const fare = Number(getBookingNegotiationField<number | string>(booking, 'fare'));

  if (negotiationStatus === 'pending' && negotiationActor === 'driver' && Number.isFinite(driverBid)) {
    return driverBid;
  }

  if (negotiationStatus === 'pending' && negotiationActor === 'consumer' && Number.isFinite(consumerBid)) {
    return consumerBid;
  }

  if (Number.isFinite(negotiatedFare) && negotiationStatus === 'pending') {
    return negotiatedFare;
  }

  return fare;
};

const getBookingStateLabel = (booking: Booking) => {
  if (hasPendingDriverCounterOffer(booking)) return 'counter offer';
  if (hasPendingTravelerCounterOffer(booking)) return 'your offer pending';
  if (booking.status === 'confirmed') return 'booked';
  return booking.status;
};

const getListedFare = (booking: Booking) => {
  const listedFare = Number(getBookingNegotiationField<number | string>(booking, 'listedFare'));
  if (Number.isFinite(listedFare) && listedFare > 0) {
    return listedFare;
  }
  return Number(getBookingNegotiationField<number | string>(booking, 'fare'));
};

const firstPositiveFare = (booking: Booking, fields: string[]) => {
  for (const field of fields) {
    const value = Number(getBookingNegotiationField<number | string>(booking, field));
    if (Number.isFinite(value) && value > 0) {
      return value;
    }
  }
  return undefined;
};

const getTravelerListedFare = (booking: Booking) =>
  firstPositiveFare(booking, [
    'travelerListedFare',
    'riderListedFare',
    'requestedFare',
    'originalRiderOffer',
    'original_rider_offer',
    'riderOffer',
    'consumerBid',
    'fare',
    'listedFare',
  ]) ?? getListedFare(booking);

const getDriverListedFare = (booking: Booking) =>
  firstPositiveFare(booking, [
    'driverListedFare',
    'originalDriverFare',
    'original_driver_fare',
    'ridePrice',
    'ride_price',
    'price',
  ]) ?? getListedFare(booking);

const getViewerListedFare = (booking: Booking, viewer: 'consumer' | 'driver') => {
  if (viewer === 'driver') {
    return getTravelerListedFare(booking);
  }

  return getDriverListedFare(booking);
};

const shouldShowNegotiatedFareLine = (booking: Booking) => {
  const listedFare = getListedFare(booking);
  const displayFare = getNegotiationDisplayFare(booking);
  return Math.abs(displayFare - listedFare) > 0.001;
};

const shouldShowViewerNegotiatedFareLine = (booking: Booking, viewer: 'consumer' | 'driver') => {
  const listedFare = getViewerListedFare(booking, viewer);
  const displayFare = getNegotiationDisplayFare(booking);
  return Math.abs(displayFare - listedFare) > 0.001;
};

const getBookingThreadKey = (booking: Partial<Booking>) => {
  const rideId = booking.rideId || '';
  if (rideId) {
    return `${rideId}__${booking.consumerId || ''}`;
  }
  const driverId = booking.driverId || '';
  const consumerId = booking.consumerId || '';
  const origin = normalizeSearchText(booking.origin || '');
  const destination = normalizeSearchText(booking.destination || '');
  return `${driverId}__${consumerId}__${origin}__${destination}`;
};

const getRecordTimestamp = (record: { updatedAt?: string; createdAt?: string }) =>
  new Date(record.updatedAt || record.createdAt || 0).getTime();

const dedupeBookingsByThread = <T extends Booking>(bookings: T[]) => {
  const latestByThread = new Map<string, T>();

  bookings.forEach((booking) => {
    const threadKey = getBookingThreadKey(booking);
    const existing = latestByThread.get(threadKey);
    if (!existing || getRecordTimestamp(booking) >= getRecordTimestamp(existing)) {
      latestByThread.set(threadKey, booking);
    }
  });

  return Array.from(latestByThread.values());
};

const getBookingRenderSignature = (booking: Booking) =>
  (() => {
    const communicationThread = getBookingNegotiationField<BookingCommunicationMessage[]>(booking, 'communicationThread') || [];
    const latestMessage = communicationThread[communicationThread.length - 1];
    return [
      booking.id,
      booking.rideId,
      booking.status,
      booking.negotiationStatus,
      booking.negotiationActor,
      booking.rideLifecycleStatus,
      booking.fare,
      (booking as any).listedFare,
      (booking as any).travelerListedFare,
      (booking as any).requestedFare,
      (booking as any).driverListedFare,
      booking.negotiatedFare,
      (booking as any).driverBid,
      (booking as any).consumerBid,
      booking.origin,
      booking.destination,
      booking.driverId,
      booking.consumerId,
      booking.driverName,
      booking.consumerName,
      booking.seatsBooked,
      (booking as any).seatsAvailable,
      booking.feePaid,
      booking.driverFeePaid,
      booking.rideStartedAt,
      booking.rideEndedAt,
      (booking as any).rideRetired,
      communicationThread.length,
      latestMessage?.sourceText || '',
      latestMessage?.translatedText || '',
      latestMessage?.createdAt || '',
    ].join('|');
  })();

const areBookingRenderListsEqual = (current: Booking[], next: Booking[]) => {
  if (current.length !== next.length) return false;
  return current.every((booking, index) => getBookingRenderSignature(booking) === getBookingRenderSignature(next[index]));
};

const mergeNegotiationThread = (bookings: Booking[], updatedThread: Booking) =>
  dedupeBookingsByThread([
    updatedThread,
    ...bookings.map((booking) =>
      getBookingThreadKey(booking) === getBookingThreadKey(updatedThread) ? updatedThread : booking
    ),
  ]).sort(
    (a, b) =>
      new Date((b as any).updatedAt || b.createdAt).getTime() -
      new Date((a as any).updatedAt || a.createdAt).getTime()
  );

const normalizeUiLanguageCode = (value?: string) =>
  getSupportedUiLanguage(String(value || 'en').trim().toLowerCase()).value;

const getRuntimeLanguageCode = () => {
  if (typeof document !== 'undefined' && document.documentElement.lang) {
    return normalizeUiLanguageCode(document.documentElement.lang);
  }
  if (typeof navigator !== 'undefined') {
    return normalizeUiLanguageCode(navigator.language.split('-')[0]);
  }
  return 'en';
};

const getPreciseLocationSnapshot = (): Promise<{ lat: number; lng: number; timestamp: number }> =>
  new Promise((resolve, reject) => {
    try {
      if (typeof window === 'undefined') {
        reject(new Error('Geolocation unavailable'));
        return;
      }

      const isNative =
        typeof Capacitor?.isNativePlatform === 'function' && Capacitor.isNativePlatform();

      if (isNative && typeof Geolocation?.getCurrentPosition === 'function') {
        Geolocation.getCurrentPosition({
          enableHighAccuracy: true,
          timeout: 8000,
          maximumAge: 0,
        })
          .then((pos) => {
            const lat = Number(pos?.coords?.latitude);
            const lng = Number(pos?.coords?.longitude);
            if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
              reject(new Error('Invalid native geolocation reading'));
              return;
            }
            resolve({ lat, lng, timestamp: Date.now() });
          })
          .catch((error) => reject(error));
        return;
      }

      if (typeof navigator === 'undefined' || typeof navigator.geolocation?.getCurrentPosition !== 'function') {
        reject(new Error('Geolocation not supported'));
        return;
      }

      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const lat = Number(pos?.coords?.latitude);
          const lng = Number(pos?.coords?.longitude);
          if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
            reject(new Error('Invalid geolocation reading'));
            return;
          }
          resolve({ lat, lng, timestamp: Date.now() });
        },
        (error) => reject(error),
        { enableHighAccuracy: true, timeout: 8000, maximumAge: 0 }
      );
    } catch (error) {
      reject(error instanceof Error ? error : new Error('Geolocation failed'));
    }
  });

const getSpeechRecognitionConstructor = () => {
  try {
    if (typeof window === 'undefined') return null;
    return window.SpeechRecognition || window.webkitSpeechRecognition || null;
  } catch {
    return null;
  }
};

const resolveSpeechLocale = (language?: string) => {
  const normalized = normalizeUiLanguageCode(language);
  const localeMap: Record<string, string> = {
    en: 'en-US',
    hi: 'hi-IN',
    bn: 'bn-IN',
    ne: 'ne-NP',
    gu: 'gu-IN',
    mr: 'mr-IN',
    ta: 'ta-IN',
    te: 'te-IN',
    kn: 'kn-IN',
    ml: 'ml-IN',
    pa: 'pa-IN',
    as: 'as-IN',
    or: 'or-IN',
    pt: 'pt-PT',
    es: 'es-ES',
    nl: 'nl-NL',
    fr: 'fr-FR',
    de: 'de-DE',
    it: 'it-IT',
    ar: 'ar-SA',
    ja: 'ja-JP',
    ko: 'ko-KR',
    zh: 'zh-CN',
    ru: 'ru-RU',
    tr: 'tr-TR',
    pl: 'pl-PL',
    uk: 'uk-UA',
    vi: 'vi-VN',
    th: 'th-TH',
    id: 'id-ID',
    ms: 'ms-MY',
    sv: 'sv-SE',
    no: 'nb-NO',
    da: 'da-DK',
    fi: 'fi-FI',
    cs: 'cs-CZ',
    hu: 'hu-HU',
    ro: 'ro-RO',
    el: 'el-GR',
    he: 'he-IL',
    fa: 'fa-IR',
  };

  if (typeof navigator !== 'undefined' && navigator.language?.toLowerCase().startsWith(normalized)) {
    return navigator.language;
  }

  return localeMap[normalized] || 'en-US';
};

const useSpeechToText = (
  language: string,
  onTranscript: (text: string) => void
) => {
  const recognitionRef = useRef<BrowserSpeechRecognitionInstance | null>(null);
  const lastTranscriptRef = useRef('');
  const [isListening, setIsListening] = useState(false);
  const [speechError, setSpeechError] = useState<string | null>(null);
  const isSupported = Boolean(getSpeechRecognitionConstructor());

  const stopListening = useCallback(() => {
    recognitionRef.current?.stop();
    recognitionRef.current = null;
    setIsListening(false);
  }, []);

  const startListening = useCallback(() => {
    const RecognitionCtor = getSpeechRecognitionConstructor();
    if (!RecognitionCtor) {
      setSpeechError('Voice input is not supported on this device/browser yet.');
      return;
    }

    recognitionRef.current?.abort();
    const recognition = new RecognitionCtor();
    recognition.lang = resolveSpeechLocale(language);
    recognition.interimResults = false;
    recognition.continuous = false;
    recognition.maxAlternatives = 1;
    lastTranscriptRef.current = '';

    recognition.onresult = (event) => {
      const nextFinalTranscripts: string[] = [];
      for (let index = event.resultIndex; index < event.results.length; index += 1) {
        if (event.results[index]?.isFinal) {
          nextFinalTranscripts.push(String(event.results[index][0]?.transcript || '').trim());
        }
      }
      const normalizedTranscript = nextFinalTranscripts.join(' ').trim();
      if (normalizedTranscript && normalizedTranscript !== lastTranscriptRef.current) {
        lastTranscriptRef.current = normalizedTranscript;
        onTranscript(normalizedTranscript);
      }
    };

    recognition.onerror = (event) => {
      if (event.error !== 'aborted') {
        setSpeechError(`Voice input issue: ${event.error}`);
      }
      setIsListening(false);
    };

    recognition.onend = () => {
      recognitionRef.current = null;
      lastTranscriptRef.current = '';
      setIsListening(false);
    };

    setSpeechError(null);
    recognitionRef.current = recognition;
    setIsListening(true);
    recognition.start();
  }, [language, onTranscript]);

  useEffect(() => () => {
    recognitionRef.current?.abort();
    recognitionRef.current = null;
  }, []);

  return {
    isSupported,
    isListening,
    speechError,
    startListening,
    stopListening,
  };
};

const getCommunicationThread = (booking: Booking): BookingCommunicationMessage[] => {
  const raw = getBookingNegotiationField<BookingCommunicationMessage[]>(booking, 'communicationThread');
  if (!Array.isArray(raw)) return [];
  return raw
    .filter((message) => message && typeof message.sourceText === 'string')
    .sort(
      (a, b) =>
        new Date(a.createdAt || 0).getTime() -
        new Date(b.createdAt || 0).getTime()
    );
};

const getLanguageDisplayName = (value?: string) => {
  const normalized = normalizeUiLanguageCode(value);
  const option = getSupportedUiLanguage(normalized);
  return option.nativeLabel || option.label;
};

