const RouteAlertsTicker = ({
  alerts,
  title,
  actionLabel,
  onAction,
}: {
  alerts: RouteAlertItem[];
  title: string;
  actionLabel?: string;
  onAction?: () => void;
}) => {
  const effectiveAlerts = alerts.length
    ? alerts
    : [
        {
          id: 'route-watch-standby',
          severity: 'info' as const,
          title: 'Route watch on standby',
          body: 'No active corridor alert right now. As soon as a live route, detour, or traffic-sensitive match is detected, updates will appear here automatically.',
        },
      ];

  const repeatedAlerts = [...effectiveAlerts, ...effectiveAlerts];

  return (
    <div className="mb-6 overflow-hidden rounded-[24px] border border-mairide-secondary bg-white shadow-sm">
      <div className="flex items-center justify-between gap-3 border-b border-mairide-secondary/60 px-4 py-3">
        <div className="flex items-center gap-3">
          <AlertTriangle className="h-4 w-4 text-mairide-accent" />
          <p className="text-[11px] font-bold uppercase tracking-[0.28em] text-mairide-secondary">{title}</p>
        </div>
        {actionLabel && onAction && (
          <button
            type="button"
            onClick={onAction}
            className="inline-flex items-center gap-2 rounded-2xl border border-mairide-secondary bg-mairide-bg px-4 py-2 text-xs font-bold text-mairide-primary transition-all hover:border-mairide-accent hover:text-mairide-accent"
          >
            <AlertTriangle className="h-3.5 w-3.5" />
            {actionLabel}
          </button>
        )}
      </div>
      <div className="overflow-hidden px-4 py-3">
        <motion.div
          className="flex min-w-max gap-3"
          animate={{ x: ['0%', '-50%'] }}
          transition={{ duration: Math.max(18, effectiveAlerts.length * 8), repeat: Infinity, ease: 'linear' }}
        >
          {repeatedAlerts.map((alert, index) => (
            <div
              key={`${alert.id}-${index}`}
              className={cn(
                "flex min-w-[320px] max-w-[420px] items-start gap-3 rounded-2xl border px-4 py-3",
                alert.severity === 'caution'
                  ? "border-red-200 bg-red-50"
                  : alert.severity === 'watch'
                    ? "border-orange-200 bg-orange-50"
                    : "border-blue-200 bg-blue-50"
              )}
            >
              <AlertCircle
                className={cn(
                  "mt-0.5 h-4 w-4 shrink-0",
                  alert.severity === 'caution'
                    ? "text-red-500"
                    : alert.severity === 'watch'
                      ? "text-orange-500"
                      : "text-blue-500"
                )}
              />
              <div className="min-w-0">
                <p className="text-sm font-bold text-mairide-primary">{alert.title}</p>
                <p className="mt-1 text-xs leading-relaxed text-mairide-secondary">{alert.body}</p>
              </div>
            </div>
          ))}
        </motion.div>
      </div>
    </div>
  );
};

const DASHBOARD_MAP_CONTAINER_STYLE: React.CSSProperties = {
  position: 'absolute',
  inset: 0,
  width: '100%',
  height: '100%',
  maxWidth: '100%',
  margin: 0,
  padding: 0,
};

const useDeferredDashboardSurface = () => {
  const preferDeferred =
    typeof window !== 'undefined' &&
    (isAndroidWebViewLikeRuntime() || isAppWebViewRuntime() || isIosAppRuntime());
  const [ready, setReady] = useState(!preferDeferred);

  useEffect(() => {
    if (!preferDeferred) {
      setReady(true);
      return;
    }

    let cancelled = false;
    let timeoutId: number | null = null;
    const frameId = window.requestAnimationFrame(() => {
      timeoutId = window.setTimeout(() => {
        if (!cancelled) setReady(true);
      }, 700);
    });

    return () => {
      cancelled = true;
      window.cancelAnimationFrame(frameId);
      if (timeoutId !== null) window.clearTimeout(timeoutId);
    };
  }, [preferDeferred]);

  return ready;
};

const triggerGoogleMapResize = (map: google.maps.Map | null | undefined) => {
  if (!map || typeof window === 'undefined' || !window.google?.maps?.event) return;
  try {
    window.google.maps.event.trigger(map, 'resize');
    const center = map.getCenter?.();
    if (center) map.setCenter(center);
  } catch {
    // Ignore transient WebView map resize failures during startup.
  }
};

const ResponsiveDashboardGoogleMap = ({
  center,
  zoom,
  options,
  children,
}: {
  center: { lat: number; lng: number };
  zoom: number;
  options?: google.maps.MapOptions;
  children?: React.ReactNode;
}) => {
  const mapRef = useRef<google.maps.Map | null>(null);
  const safeCenter = useMemo(() => {
    const lat = Number(center?.lat);
    const lng = Number(center?.lng);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
      return { lat: 26.1433, lng: 91.7385 };
    }
    return { lat, lng };
  }, [center?.lat, center?.lng]);

  useEffect(() => {
    const handleResize = () => triggerGoogleMapResize(mapRef.current);
    window.addEventListener('resize', handleResize);
    window.addEventListener('orientationchange', handleResize);
    const settleTimer = window.setTimeout(handleResize, 220);
    return () => {
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('orientationchange', handleResize);
      window.clearTimeout(settleTimer);
    };
  }, []);

  return (
    <GoogleMap
      mapContainerStyle={DASHBOARD_MAP_CONTAINER_STYLE}
      mapContainerClassName="absolute inset-0 h-full w-full max-w-full overflow-hidden"
      center={safeCenter}
      zoom={zoom}
      onLoad={(map) => {
        mapRef.current = map;
        window.requestAnimationFrame(() => triggerGoogleMapResize(map));
      }}
      options={options}
    >
      {children}
    </GoogleMap>
  );
};

const getGoogleMapsDiagnostic = ({
  isLoaded,
  loadError,
  authFailure,
}: {
  isLoaded: boolean;
  loadError?: Error | null;
  authFailure: boolean;
}) => {
  if (!GOOGLE_MAPS_API_KEY) {
    return 'Missing VITE_GOOGLE_MAPS_API_KEY in the active environment.';
  }
  if (authFailure) {
    return 'Google Maps authentication failed. Check referrer restrictions, enabled Maps JavaScript API, and billing.';
  }
  const message = String(loadError?.message || '');
  if (/RefererNotAllowedMapError/i.test(message)) {
    return 'Referrer mismatch. Add this localhost origin and rides.mairide.in to Google Cloud HTTP referrer restrictions.';
  }
  if (/InvalidKeyMapError/i.test(message)) {
    return 'Invalid Google Maps API key. Verify VITE_GOOGLE_MAPS_API_KEY is from the correct Google Cloud project.';
  }
  if (/ApiNotActivatedMapError/i.test(message)) {
    return 'Maps JavaScript API is not enabled for this Google Cloud project.';
  }
  if (/BillingNotEnabledMapError/i.test(message)) {
    return 'Billing is not enabled for this Google Cloud project.';
  }
  if (message) {
    return message;
  }
  if (!isLoaded) {
    return 'Google Maps JavaScript API is still loading.';
  }
  if (typeof window !== 'undefined' && !window.google) {
    return 'Google Maps loaded flag resolved, but window.google is not available yet.';
  }
  return 'Google Maps is not ready yet.';
};

const DashboardGoogleMapUnavailable = ({
  isLoaded,
  loadError,
  authFailure,
}: {
  isLoaded: boolean;
  loadError?: Error | null;
  authFailure: boolean;
}) => {
  const showDevDiagnostics = isLocalhostRuntime();
  const diagnostic = showDevDiagnostics
    ? getGoogleMapsDiagnostic({ isLoaded, loadError, authFailure })
    : '';
  return (
    <div
      className="absolute inset-0 h-full w-full bg-[radial-gradient(circle_at_52%_34%,rgba(242,116,38,0.12),transparent_30%),linear-gradient(135deg,#eef3f5_0%,#dbe4e8_100%)]"
      aria-label="Google map loading"
    >
      {showDevDiagnostics ? (
        <div className="absolute left-4 top-24 z-10 max-w-sm rounded-2xl border border-red-200 bg-white/95 p-4 text-left shadow-xl backdrop-blur-md">
          <p className="text-[11px] font-black uppercase tracking-[0.22em] text-red-600">Google Maps Dev Diagnostic</p>
          <p className="mt-2 text-sm font-bold text-mairide-primary">{diagnostic}</p>
          <p className="mt-2 text-xs font-semibold text-mairide-secondary">
            Key prefix: {GOOGLE_MAPS_API_KEY ? `${GOOGLE_MAPS_API_KEY.slice(0, 8)}...` : 'missing'}
          </p>
        </div>
      ) : null}
    </div>
  );
};

